import { throttle } from "./utils.js";
/** Native DnD with an exact placeholder; app provides one validated dispatch callback. */
export function bindDragDrop(root, move, reorderColumn = () => {}) { let taskId = null, columnId = null, placeholder = null; const clear = () => { placeholder?.remove(); placeholder = null; root.querySelectorAll(".is-dragging,.drop-column-target,.is-column-dragging").forEach((n) => n.classList.remove("is-dragging", "drop-column-target", "is-column-dragging")); };
  root.addEventListener("dragstart", (event) => { const card = event.target.closest(".task-card"), header = event.target.closest(".column-header"); if (card) { taskId = card.dataset.taskId; card.classList.add("is-dragging"); event.dataTransfer.effectAllowed = "move"; } else if (header) { columnId = header.dataset.columnId; header.closest(".kanban-column").classList.add("is-column-dragging"); } });
  root.addEventListener("dragover", throttle((event) => { const list = event.target.closest(".column-cards"); if (!list || !taskId) return; event.preventDefault(); const cards = [...list.querySelectorAll(".task-card:not(.is-dragging)")]; const before = cards.find((card) => event.clientY < card.getBoundingClientRect().top + card.getBoundingClientRect().height / 2); if (!placeholder) placeholder = document.createElement("div"), placeholder.className = "drop-placeholder"; if (before) list.insertBefore(placeholder, before); else list.append(placeholder); list.closest(".kanban-column").classList.add("drop-column-target"); }, 50));
  root.addEventListener("dragover", (event) => { if (!columnId) return; const target = event.target.closest(".kanban-column"); if (target) { event.preventDefault(); target.classList.add("drop-column-target"); } });
  root.addEventListener("drop", (event) => { const list = event.target.closest(".column-cards"), targetColumn = event.target.closest(".kanban-column"); if (taskId && list) { event.preventDefault(); const cards = [...list.querySelectorAll(".task-card:not(.is-dragging)")]; const index = placeholder ? [...list.children].indexOf(placeholder) : cards.length; move(taskId, list.dataset.dropColumn, index); } else if (columnId && targetColumn) { event.preventDefault(); const columns = [...root.querySelectorAll(".kanban-column")]; reorderColumn(columnId, columns.indexOf(targetColumn)); } clear(); taskId = null; columnId = null; }); root.addEventListener("dragend", () => { clear(); taskId = null; columnId = null; }); return () => {};
}
